#[derive(Clone, Debug, Default, PartialEq)]
pub struct OrdnanceHostUnit {
    pub alive: bool,
    pub dead: bool,
    pub removed: bool,
    pub shapes: u32,
    pub seat: u32,
    pub exposed: bool,
    pub vehicle: u32,
    pub vehicle_body: u32,
    pub turret_body: u32,
    pub center: Vec3,
    pub radius: f64,
}

impl OrdnanceHostUnit {
    pub const WORDS: usize = 13;
    pub const ALIVE: usize = 0;
    pub const DEAD: usize = 1;
    pub const REMOVED: usize = 2;
    pub const SHAPES: usize = 3;
    pub const SEAT: usize = 4;
    pub const EXPOSED: usize = 5;
    pub const VEHICLE: usize = 6;
    pub const VEHICLE_BODY: usize = 7;
    pub const TURRET_BODY: usize = 8;
    pub const CENTER: usize = 9;
    pub const RADIUS: usize = 12;

    pub fn put(&self, row: &mut [f64], heap: &mut Vec<f64>) {
        let row: &mut [f64; 13] = (&mut row[..13]).try_into().unwrap();
        row[0] = if self.alive { 1.0 } else { 0.0 };
        row[1] = if self.dead { 1.0 } else { 0.0 };
        row[2] = if self.removed { 1.0 } else { 0.0 };
        row[3] = self.shapes as f64;
        row[4] = self.seat as f64;
        row[5] = if self.exposed { 1.0 } else { 0.0 };
        row[6] = self.vehicle as f64;
        row[7] = self.vehicle_body as f64;
        row[8] = self.turret_body as f64;
        row[9..9 + 3].copy_from_slice(&self.center);
        row[12] = self.radius;
    }

    pub fn take(row: &[f64], heap: &[f64]) -> Self {
        let row: &[f64; 13] = (&row[..13]).try_into().unwrap();
        Self {
            alive: row[0] != 0.0,
            dead: row[1] != 0.0,
            removed: row[2] != 0.0,
            shapes: word_u32(row[3]),
            seat: word_u32(row[4]),
            exposed: row[5] != 0.0,
            vehicle: word_u32(row[6]),
            vehicle_body: word_u32(row[7]),
            turret_body: word_u32(row[8]),
            center: [row[9], row[9 + 1], row[9 + 2]],
            radius: row[12],
        }
    }

}

